plant = TransferFunctionModel[1/((s + 1)^3), s];
{c, cl} = PIDTune[plant, "PID", {"Controller", "ClosedLoopSystem"}];
Plot[Evaluate@OutputResponse[cl, UnitStep[t], {t, 0, 25}], {t, 0, 25}]

a = TransferFunctionModel[1/(s + 1), s];
b = TransferFunctionModel[2/(s + 3), s];
SystemsModelSeriesConnect[a, b]

plant = TransferFunctionModel[10/(s (s + 2)), s];
cl = SystemsModelFeedbackConnect[plant];
BodePlot[cl]

ssm = StateSpaceModel[{{{0, 1}, {-2, -3}}, {{0}, {1}}, IdentityMatrix[2], 0}];
k = StateFeedbackGains[ssm, {-4, -5}];
cl = SystemsModelStateFeedbackConnect[ssm, k]

proto = ButterworthFilterModel[3];
hp = TransferFunctionTransform[1/# &, proto];
BodePlot[hp]

